#!/usr/bin/env python3
"""Java 1.21.9／1.21.10（プロトコル773）の Bedrock→Java バックエンド対応を入れる。

対象: detergentmc-bedrock の JavaBackendConnection（773 サーバーとの
入出力）と BedrockEntityTranslator／BedrockChunkTranslator（773 の
ID を 765 に正規化）。772の流儀をなぞる。

773 で新たに必要なもの（772 には無かった）は無い。772と違うのは：
- アイテム（銅の道具×5・銅の防具×4・銅ゴーレムのスポーンエッグ・
  銅の馬鎧・銅の塊など73件新規、1,416→1,488）・音（43件新規、
  1,728→1,771）・パーティクル（copper_fire_flame が5番に挿入、
  114→115）。ブロック状態（27,946→29,671）・エンティティ
  （銅ゴーレム27・マネキン82、151→153）・ブロックエンティティ
  （shelf 40番挿入・copper_golem_statue 48番追加、47→49）。
  絵画（51件）・ジュークボックスの歌（21件）・バイオーム（65件）・
  エンチャント（42件）・メニュー（25件）・属性（35件）・
  データコンポーネント（96件）は772と同一。
- Join Game／Player Info／Synchronize Player Position／Update Attributes／
  Client Information／Chat Message／チャンクの heightmap／パレット付き
  コンテナ／Entity Metadata の型番号／粒子IDは772と同一のため、既存の
  772分岐に773を足すだけで済む（実バニラ1.21.9／1.21.10のプローブは未実施）。
- 属性は772と同一（attributeName773 は772と同じ内容）。
- エンティティは772と同一（happy_ghast は772=56、773=57。対応表で処理）。
  銅ゴーレム／マネキンは対応表でブタへ。
- 正規化は mapEntityType773To765／mapItem773To765／
  mapBlockState773To765／mapParticle773To765（ステージBで追加済み）で行う。

それ以外は772と同形で、既存の772分岐に773を足すだけで済む。
実機 Bedrock クライアントでの確認は未実施（既存の全 Bedrock 組み合わせと同様）。
各アンカーはファイル中にちょうど1回だけ現れること。
"""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent  # detergentmc-protocol/
BEDROCK = ROOT.parent / "detergentmc-bedrock" / "src" / "main" / "java" \
    / "io" / "detergentmc" / "bedrock"


def edit(path, pairs):
    src = path.read_text(encoding="utf-8")
    for label, old, new in pairs:
        n = src.count(old)
        if n != 1:
            print(f"NG: {path.name} {label}: anchor が {n} 回見つかった（1回のはず）",
                  file=sys.stderr)
            sys.exit(1)
        src = src.replace(old, new)
        print(f"OK: {path.name} {label}")
    path.write_text(src, encoding="utf-8")


